import{at as e,it as t,n,vt as r}from"./chunks/framework.fhiXEbOi.js";var i=JSON.parse(`{"title":"Deploy","description":"Choose viewer hosting, a new app deployment, publication updates, recovery or local release practice.","frontmatter":{"title":"Deploy","description":"Choose viewer hosting, a new app deployment, publication updates, recovery or local release practice.","outline":false},"headers":[],"relativePath":"deploy/index.md","filePath":"deployment/index.md"}`),a={name:`deploy/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="choose-a-deployment-task" tabindex="-1">Choose a deployment task <a class="header-anchor" href="#choose-a-deployment-task" aria-label="Permalink to “Choose a deployment task”">​</a></h1><div class="ported-guide"><p id="scope">Hosting viewer software, publishing workflow files and deploying contracts are different jobs. Choose the outcome below; each procedure states its prerequisites and what it changes.</p><p>To open an app that is already deployed, use the <a href="../gallery/">Gallery</a>. None of the operator procedures below is needed just to browse.</p><h2 id="deploy-to-the-selected-chain">Create or host<span id="prepare"></span></h2><dl class="task-routes"><dt><a href="./new-instance.html">Deploy a new app instance</a></dt><dd>Create contracts and a CAM publication through separately approved transactions, with an explicit pause to host the files.</dd><dt><a href="./viewer.html">Host the stand-alone viewer</a></dt><dd>Serve browser software at your own HTTPS hostname. This creates no contracts or CAM publication.</dd><dt id="view-cam-publication"><a href="../use/#local-publication">Open a saved publication locally</a></dt><dd>Inspect existing contracts using the retained instance and a browser-accessible RPC.</dd></dl><h2 id="publish-prepared-cam">Maintain an existing instance<span id="host-the-prepared-bundle"></span></h2><dl class="task-routes"><dt id="update-an-existing-ui"><a href="./update.html">Update a published app</a></dt><dd>Choose a compatible CAM-only change, projection replacement or an explicit business-contract migration. Preparation does not publish.</dd><dt id="complete-deployment-records"><span id="complete-component-records"></span><a href="./recovery.html">Recover an interrupted release</a></dt><dd>Inspect retained evidence and resume only what remains. Do not start another deployment to repair incomplete records. <span id="cancel-a-release-or-rehearsal"></span>See its <a href="./recovery.html#stop">stop and cancellation procedure</a> for uncertain outcomes.</dd><dt id="source-publication"><span id="source-publication-recovery"></span><a href="./source-verification.html">Publish or recheck contract sources</a></dt><dd>Verify the original compiler inputs with Sourcify. A failed verification request does not undo a deployment.</dd></dl><h2 id="rehearse-the-release-locally">Practice and prepare</h2><dl class="task-routes"><dt id="start-a-local-network-then-deploy-manually"><span id="view-an-existing-local-release"></span><a href="./practice.html">Rehearse the release workflow</a></dt><dd>Use a retained local chain or an isolated approval/publication rehearsal, without public funds.</dd><dt id="rehearse-approval-startup-and-rejection"><span id="rehearse-a-successful-approval"></span><a href="./practice.html#approval">Test an approval image</a></dt><dd>Exercise the reviewed approval input and fixture-only acceptance or rejection. For a simpler first experience, follow the <a href="../start/local-wallet.html">local-wallet tutorial</a>.</dd></dl><h2 id="app-settings">App-specific settings</h2><p>Choose the business contract&#39;s authorities and configuration before starting the shared deployment procedure:</p><p><a href="./bike-nft/">Bike NFT</a> · <a href="./escrow/">Escrow</a> · <a href="./pay-to-play/">Pay-to-Play</a>.</p><h2 id="independent-components">Operational reference<span id="release-records"></span><span id="ui-signing-configuration"></span></h2><p>For the underlying evidence, authority and runtime boundaries, consult the <a href="../reference/operations.html">operations reference</a>. <span id="docker-identity"></span>Its <a href="../reference/operations.html#identity">Docker identity</a> section covers private-file access, while <span id="accept-the-selected-authorities"></span><a href="../reference/operations.html#handoffs">handoffs</a> explains separate nominee acceptance.</p><p id="progress-and-bounded-diagnostics"><span id="explicit-simulation-comparison"></span>For failed operations, use <a href="../reference/diagnostics.html">bounded diagnostics</a>. For transport choices, use <a href="./networks/">Networks</a> and <a href="./rpc/">RPC services</a>. Catalog entries do not authenticate contracts.</p></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};